async function exportPdf(ws) {
  try {
    if (!(window.jspdf && window.jspdf.jsPDF)) {
      await new Promise((res, rej) => {
        const s = document.createElement("script");
        s.src = "/vendor/jspdf.umd.min.js";
        s.onload = res;
        s.onerror = rej;
        document.head.appendChild(s);
      });
    }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: "pt", format: "a4" });
    const ex = ws.executive, re = ws.research;
    let y = 56;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(20);
    doc.text("Summer School Analytics", 40, y);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(120);
    y += 18;
    doc.text(`${ws.filters.rangeLabel} \xB7 generated ${new Date(ws.generatedAt).toLocaleString()}`, 40, y);
    doc.setTextColor(20);
    y += 26;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Executive summary", 40, y);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    y += 16;
    const kv = [
      ["Total students", ex.totalStudents],
      ["Centres", ex.centres],
      ["Faculties", ex.departments],
      ["Attendance rate", ex.attendanceRate + "%"],
      ["Weekly growth", (ex.weeklyGrowth > 0 ? "+" : "") + ex.weeklyGrowth + "%"],
      ["Assessments", `${ex.assessments.total} (${ex.assessments.graded} graded)`],
      ["Activities", ex.activities],
      ["Best centre", ex.bestCentre ? `${ex.bestCentre.name} (${ex.bestCentre.rate}%)` : "\u2014"]
    ];
    const pr = re.retention && re.retention.children > 0 ? re.retention : null;
    if (pr) kv.push(
      ["Still coming", `${pr.stillComing} of ${pr.children}`],
      ["Came then stopped", `${pr.stopped} (${pr.stoppedPct}%) over ${pr.openDays} sessions`]
    );
    kv.forEach(([k, v]) => {
      doc.text(`${k}:`, 48, y);
      doc.setFont("helvetica", "bold");
      doc.text(String(v), 200, y);
      doc.setFont("helvetica", "normal");
      y += 15;
    });
    y += 12;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Centre comparison", 40, y);
    y += 8;
    doc.setFontSize(9);
    if (pr) {
      doc.setTextColor(120);
      y += 12;
      doc.text(`Att% is ${ws.filters.rangeLabel}; Stopped is the whole term, ${pr.from} to ${pr.to}.`, 48, y);
      doc.setTextColor(20);
    }
    const cols = [["Centre", 48], ["Students", 200], ["Att%", 262], ["Grade", 306], ["Acts", 352], ["Stars", 396]].concat(pr ? [["Stopped", 440]] : []);
    y += 12;
    doc.setFont("helvetica", "bold");
    cols.forEach(([t, x]) => doc.text(t, x, y));
    doc.setFont("helvetica", "normal");
    y += 4;
    doc.setDrawColor(220);
    doc.line(40, y, 500, y);
    y += 12;
    re.centreComparison.forEach((c) => {
      if (y > 780) {
        doc.addPage();
        y = 56;
      }
      doc.text(String(c.name).slice(0, 22), 48, y);
      doc.text(String(c.enrolled), 200, y);
      doc.text(String(c.attendanceRate), 262, y);
      doc.text(String(c.avgGrade ?? "\u2014"), 306, y);
      doc.text(String(c.activities), 352, y);
      doc.text(String(c.stars), 396, y);
      if (pr) doc.text((c.stopped || 0) > 0 ? `${c.stopped} (${c.stoppedPct}%)` : "none", 440, y);
      y += 14;
    });
    y += 16;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Statistical summary", 40, y);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    y += 16;
    doc.text(`Attendance \u2014 mean ${re.stats.attendance.mean}%, median ${re.stats.attendance.median}%, SD ${re.stats.attendance.sd} (n=${re.stats.attendance.n})`, 48, y);
    y += 14;
    doc.text(`Grades \u2014 mean ${re.stats.grades.mean}, median ${re.stats.grades.median}, SD ${re.stats.grades.sd} (n=${re.stats.grades.n})`, 48, y);
    doc.save("ngg-analytics-" + (ws.filters.rangeLabel || "all").replace(/\s+/g, "-") + ".pdf");
  } catch (e) {
    alert("PDF export unavailable: " + (e.message || e));
  }
}
